def sortieren(liste):
    liste = list(liste)
    for i in range(len(liste)):
        for j in range(len(liste) - 1 - i):
            if liste[j] > liste[j + 1]:
                liste[j], liste[j + 1] = liste[j + 1], liste[j]
    return liste

print(sortieren([5, 2, 9, 1]))  # [1, 2, 5, 9]

